export const contactConfig={creator:'Muhammad Rizky',whatsappNumber:'6281393177004',placeholder:false};
export function normalizeWhatsAppNumber(value){const n=String(value??'').trim().replace(/[\s()+.-]/g,'');if(!/^[1-9]\d{7,14}$/.test(n))throw Error('Use an international WhatsApp number.');return n;}
export function buildWhatsAppUrl(number,request,pageUrl){const url=new URL('https://wa.me/'+normalizeWhatsAppNumber(number)),page=new URL(pageUrl);page.search='';page.hash='';url.searchParams.set('text',`Hi ${contactConfig.creator}, I visited RIZKY ATELIER and would like to request ${request}.\n\nReference: ${page.href}\nThank you.`);return url.href;}
export function syncScroll(){document.body.style.overflow=document.querySelector('dialog[open]')||document.body.classList.contains('viewer-expanded')?'hidden':'';}
export function initContact(){const dialog=document.querySelector('#contact-dialog'),link=document.querySelector('#contact-whatsapp');let trigger;
 document.addEventListener('click',e=>{const button=e.target.closest('[data-download-request]');if(!button)return;e.preventDefault();trigger=button;const request=button.dataset.downloadRequest||'the complete Rizky Atelier project';document.querySelector('#contact-request').textContent=request;try{if(contactConfig.placeholder)throw Error('Contact inactive');link.href=buildWhatsAppUrl(contactConfig.whatsappNumber,request,location.href);link.removeAttribute('aria-disabled');document.querySelector('#contact-unavailable').hidden=true;}catch{link.removeAttribute('href');link.setAttribute('aria-disabled','true');document.querySelector('#contact-unavailable').hidden=false;}document.dispatchEvent(new Event('atelier:modal'));if(!dialog.open)dialog.showModal();syncScroll();(link.hasAttribute('href')?link:document.querySelector('#close-contact')).focus({preventScroll:true});});
 document.querySelector('#close-contact').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.x||e.clientX>r.right||e.clientY<r.y||e.clientY>r.bottom)dialog.close();});dialog.addEventListener('close',()=>{syncScroll();if(trigger?.isConnected)trigger.focus({preventScroll:true});});
}
